insert into job_categories(name_en,name_bn,slug)values('Construction','নির্মাণ','construction'),('Hospitality','হসপিটালিটি','hospitality'),('Driving','ড্রাইভিং','driving'),('Manufacturing','ম্যানুফ্যাকচারিং','manufacturing')on conflict(slug)do nothing;
insert into countries(name_en,name_bn,iso_code,description_bn)values('United Arab Emirates','সংযুক্ত আরব আমিরাত','AE','আন্তর্জাতিক কর্মসংস্থানের সুযোগের তথ্য।'),('Saudi Arabia','সৌদি আরব','SA','প্রকাশিত সুযোগের শর্ত যাচাই করুন।'),('Qatar','কাতার','QA','সুযোগ সংশ্লিষ্ট নিয়োগকর্তার প্রক্রিয়ার ওপর নির্ভরশীল।')on conflict do nothing;
insert into faqs(question_bn,answer_bn,"order")values('চাকরি কি নিশ্চিত করা হয়?','না। আমরা সহায়তা ও সমন্বয় করি; চাকরি বা ভিসা নিশ্চিত করি না।',1),('রেজিস্ট্রেশনে কী লাগবে?','সঠিক ব্যক্তিগত, শিক্ষাগত, অভিজ্ঞতা ও পাসপোর্ট সংক্রান্ত তথ্য।',2),('ভিসা কি আপনারা অনুমোদন করেন?','না। ভিসা অনুমোদন সংশ্লিষ্ট কর্তৃপক্ষের বিষয়।',3)on conflict do nothing;
